var u=1024**3,e=1024**2,t=1024;function i(n,r="auto"){return n==null||n<0?"N/A":r==="GB"||r==="auto"&&n>=u?`${(n/u).toFixed(2)} GB`:r==="MB"||r==="auto"&&n>=e?`${(n/e).toFixed(1)} MB`:n>=t?`${(n/t).toFixed(0)} KB`:`${n} B`}function f(n,r=0){return n==null?"N/A":`${n.toFixed(r)}%`}function o(n,r){return!n||!r||r===0?null:Math.round(n/r*100)}function l(n,r="N/A"){return n==null||n===""?r:String(n)}function d(n){return n==null?null:Math.round(n*100)}export{i as a,f as b,o as c,l as d,d as e};
